import{_ as a,o as l,c as r,a2 as t}from"./chunks/framework.CdvW4CUT.js";const u=JSON.parse('{"title":"新手教學","description":"伺服器的新手教學，幫助新玩家快速上手。","frontmatter":{"title":"新手教學","description":"伺服器的新手教學，幫助新玩家快速上手。"},"headers":[],"relativePath":"newbie/index.md","filePath":"newbie.md"}'),i={name:"newbie/index.md"};function o(b,e,h,d,c,s){return l(),r("div",null,[...e[0]||(e[0]=[t('<h1 id="新手教學" tabindex="-1">新手教學 <a class="header-anchor" href="#新手教學" aria-label="Permalink to &quot;新手教學&quot;">​</a></h1><p>哈囉新玩家，歡迎來到風平浪靜！<br> 這邊為你準備了一些教學，幫助你能夠快速上手</p><h2 id="前言" tabindex="-1">前言 <a class="header-anchor" href="#前言" aria-label="Permalink to &quot;前言&quot;">​</a></h2><p>首先，再次歡迎你來到風平浪靜<br> 這裡是原味伺服器，沒有太多的特殊功能，玩法基本上就跟一般生存一樣</p><p>網站的左邊詳列了我們所有的設定、功能及指令的介紹<br> 我們會建議你先看完我們幫你整理在這個頁面的重點，有需要再去看左邊的說明</p><p>然後伺服器的大小事，包含公告、更新及維護等資訊，我們都會放在Discord上面<br> 我們也建議你<a href="/discord/">加入我們的Discord</a>，這樣當你遇到問題的時候可以更快的聯絡上我們(管理員)</p><p>最後，希望你會在這裡玩得開心<br> 如果有任何需要幫助的地方，或是網站上有任何需要改進的地方，歡迎隨時<a href="/contact/">聯絡我們</a></p><h2 id="伺服規定-節錄" tabindex="-1">伺服規定(節錄) <a class="header-anchor" href="#伺服規定-節錄" aria-label="Permalink to &quot;伺服規定(節錄)&quot;">​</a></h2><p>這邊整理了幾個伺服規定的重點，詳細的說明請參閱<a href="/rule/"><b>伺服規範</b></a></p><ul><li>任何公頻發言，請遵守<a href="/rule/chat/"><b>公共頻道聊天規範</b></a></li><li>請勿影響其他玩家遊玩</li><li>嚴禁使用外掛功能/遊戲BUG</li><li>請勿開分身或使用VPN遊玩</li></ul><h2 id="伺服設定" tabindex="-1">伺服設定 <a class="header-anchor" href="#伺服設定" aria-label="Permalink to &quot;伺服設定&quot;">​</a></h2><p>這邊簡單的整理了伺服器的特殊設定，詳細的說明請參閱<a href="/setting/"><b>伺服設定</b></a></p><ul><li><font color="red"><b>沒有領地及保護區</b></font><ul><li>東西被偷、被破壞可以透過<a href="/discord/">Discord</a>進行<a href="/apply/report/">檢舉回報</a><ul><li>我們會盡快幫你處理，並復原你被破壞、被偷的東西</li></ul></li></ul></li><li>防噴 <ul><li>除了<a href="/dungeon/intro/">副本服</a>的<a href="/dungeon/sp_setting/"><b>特殊情況</b></a></li></ul></li><li>防爆及防燒 <ul><li>除了<a href="/server/res/">資源服</a></li></ul></li><li>只有<a href="/server/res/">資源服</a>可以挖掘遠古遺骸；會生成魚類、夜魅及終界龍</li><li>本伺服的獄髓升級模板有更動合成方式，詳細請參考<a href="/setting/#獄髓升級模板複製方式">此處</a></li></ul><h2 id="分流介紹" tabindex="-1">分流介紹 <a class="header-anchor" href="#分流介紹" aria-label="Permalink to &quot;分流介紹&quot;">​</a></h2><p>這邊簡單的整理了伺服器各個分流的介紹，詳細的說明請參閱網站左側<b>各分流介紹</b></p><ul><li><b><a href="/server/Lobby/"><b>大廳服</b></a>：</b>伺服器的大廳，可以通往各個分流，有美術公園，未來將會有商店街 <ul><li>路上有一些特別的造景和跑酷，有興趣的話可以四處逛逛</li></ul></li><li><b><a href="/server/sv/"><b>主伺服</b></a>：</b>建築蓋家及生存的地方 <ul><li>生怪調降、關閉生怪磚功能</li><li>要蓋大型牧場及設施請前往設施服</li></ul></li><li><b><a href="/server/mh/"><b>設施服</b></a>：</b>建造紅石機關、物資塔及大型設施等的地方 <ul><li>無法繁殖綿羊，請使用<a href="/feature/sp_tool/">綿羊卷軸</a>提升單隻綿羊的產量</li></ul></li><li><b><a href="/server/res/"><b>資源服</b></a>：</b>採集資源的地方 <ul><li><font color="red"><b>沒有防爆</b></font>、<a href="/feature/lock/"><font color="red"><b>沒有鎖箱/鎖門</b></font></a></li><li>唯一會生成夜魅、終界龍及可以挖掘遠古遺骸的分流</li></ul></li><li><b><a href="/server/De/"><b>副本服</b></a>：</b>打怪賺錢的地方 <ul><li>獨立分流，詳細請參考<a href="/dungeon/intro/">副本服 簡介</a></li></ul></li></ul><h2 id="進入伺服" tabindex="-1">進入伺服 <a class="header-anchor" href="#進入伺服" aria-label="Permalink to &quot;進入伺服&quot;">​</a></h2><p>你剛加入伺服的時候會出現在這邊<br> 先把<a href="/rule/">遊玩規範</a>跟這份教學看完後再往前走吧<br><img src="https://i.imgur.com/yTs5znF.png" style="width:50%;"></p><p>再來你會出現在這裡，<b>直接往前走</b>就可以找到<a href="/server/sv/">主伺服</a>的傳送NPC<br><img src="https://i.imgur.com/fvpMibI.png" style="width:50%;"></p><p>接著<b>對NPC右鍵</b>就可以進去<a href="/server/sv/">主伺服</a>，你可以選擇要在主一或主二生存(主三是<a href="/donate/">贊助</a>/推薦限定)<br><img src="https://i.imgur.com/kd686bc.png" style="width:45%;"><img src="https://i.imgur.com/Usr3hud.png" style="width:38.6%;"></p><h2 id="找地方蓋家" tabindex="-1">找地方蓋家 <a class="header-anchor" href="#找地方蓋家" aria-label="Permalink to &quot;找地方蓋家&quot;">​</a></h2><p>進入主一或主二後，你會出現在分流重生點，在重生點附近輸入<code>/rtp</code>就可以隨機傳送<br><img src="https://i.imgur.com/84rGDD9.png" style="width:45%;"><img src="https://i.imgur.com/96SJf14.png" style="width:41.1%;"></p><p>傳送完後再繼續往外跑個2000格以上就可以蓋家了，<b>越遠越不容易有人來破壞跟偷你東西</b><br> (如果傳送後卡住了可以輸入<code>/spawn</code>，回到重生點再輸入<code>/rtp</code>重新傳送)</p><p>當你選好地方後，可以先輸入<code>/sethome &lt;家的名稱&gt;</code>紀錄home點，然後就可以準備去<a href="/server/res/">資源服</a>採集資源了<br> (無贊助的玩家會有5個home點可以使用，如果要刪除home點可以輸入<code>/delhome &lt;家的名稱&gt;</code>)</p><h2 id="採集資源" tabindex="-1">採集資源 <a class="header-anchor" href="#採集資源" aria-label="Permalink to &quot;採集資源&quot;">​</a></h2><p>首先輸入<code>/bs</code>開啟<a href="/feature/bs/">伺服幫助選單</a>，點選上方的指南針回到<a href="/server/Lobby/">大廳服</a>(一開始選分流的那個地方)<br><img src="https://i.imgur.com/y6C9NnU.png" style="width:50%;"></p><p>然後輸入<code>/spawn</code>回到重生點，向後轉180度就可以看到<a href="/server/res/">資源服</a>的傳送NPC，一樣右鍵他就可以進去了<br><img src="https://i.imgur.com/Kkh0z6i.png" style="width:50%;"></p><p>一樣輸入<code>/rtp</code>就可以隨機傳送，找好地方就可以採集資源了<br> (如果傳送後覺得位置不好可以輸入<code>/spawn</code>，回到重生點再輸入<code>/rtp</code>重新傳送)<br><img src="https://i.imgur.com/EbPnPQ1.png" style="width:50%;"></p><p>採集完資源後就可以輸入<code>/home &lt;家的名稱&gt;</code>，回到剛剛選好要蓋家的地方開始蓋你的家<br> 接下來就跟一般生存一樣了，如果有需要蓋大型牧場或設施請務必前往<a href="/server/mh/"><b>設施服</b></a></p><h2 id="常用功能與指令" tabindex="-1">常用功能與指令 <a class="header-anchor" href="#常用功能與指令" aria-label="Permalink to &quot;常用功能與指令&quot;">​</a></h2><p>這裡整理了一些常用指令，詳細的說明請參考網站左側選單的各個章節</p><h3 id="開啟新手教學連結" tabindex="-1">開啟新手教學連結 <a class="header-anchor" href="#開啟新手教學連結" aria-label="Permalink to &quot;開啟新手教學連結&quot;">​</a></h3><ul><li><code>/rule</code><b>在聊天欄顯示官網及新手教學頁面連結</b>(<code>/rules</code>也是同樣效果)</li></ul><h3 id="pvp" tabindex="-1"><a href="/feature/simple/"><b>PVP</b></a> <a class="header-anchor" href="#pvp" aria-label="Permalink to &quot;[&lt;b&gt;PVP&lt;/b&gt;](./feature/simple.md)&quot;">​</a></h3><ul><li><code>/pvp</code><b>開啟/關閉PVP</b>(資源服強制開啟，無法關閉)</li></ul><h3 id="伺服幫助選單" tabindex="-1"><a href="/feature/bs/"><b>伺服幫助選單</b></a> <a class="header-anchor" href="#伺服幫助選單" aria-label="Permalink to &quot;[&lt;b&gt;伺服幫助選單&lt;/b&gt;](./feature/bs.md)&quot;">​</a></h3><ul><li><code>/bs</code><b>開啟伺服幫助選單</b></li></ul><h3 id="聊天室" tabindex="-1"><a href="/feature/chat/"><b>聊天室</b></a> <a class="header-anchor" href="#聊天室" aria-label="Permalink to &quot;[&lt;b&gt;聊天室&lt;/b&gt;](./feature/chat.md)&quot;">​</a></h3><ul><li><code>/tell &lt;玩家ID&gt; &lt;文字&gt;</code><b>發送密語給他人</b>(/m , /msg 也是同樣效果)</li><li><code>/r &lt;文字&gt;</code><b>密語回覆上一個發送你密語的人</b></li></ul><h3 id="傳送-設定紀錄點" tabindex="-1"><a href="/feature/teleport/"><b>傳送/設定紀錄點</b></a> <a class="header-anchor" href="#傳送-設定紀錄點" aria-label="Permalink to &quot;[&lt;b&gt;傳送/設定紀錄點&lt;/b&gt;](./feature/teleport.md)&quot;">​</a></h3><h4 id="傳送" tabindex="-1">傳送 <a class="header-anchor" href="#傳送" aria-label="Permalink to &quot;傳送&quot;">​</a></h4><ul><li><code>/spawn</code><b>返回至伺服重生點</b></li><li><code>/back</code><b>回去上一個傳送點</b></li><li><code>/tpa &lt;玩家ID&gt;</code><b>請求傳送至對方那邊</b> 你--&gt;對方</li><li><code>/tpahere &lt;玩家ID&gt;</code><b>請求&quot;對方&quot;傳送至你這邊</b> 對方--&gt;你</li></ul><h4 id="設定紀錄點" tabindex="-1">設定紀錄點 <a class="header-anchor" href="#設定紀錄點" aria-label="Permalink to &quot;設定紀錄點&quot;">​</a></h4><ul><li><code>/sethome &lt;家的名稱&gt;</code><b>設定家的位置</b></li><li><code>/home &lt;家的名稱&gt;</code><b>傳送回家</b></li><li><code>/delhome &lt;家的名稱&gt;</code><b>刪除現有的家</b></li><li><code>/homelist</code><b>查看你擁有的家及位置</b></li></ul><h3 id="方塊紀錄查詢" tabindex="-1"><a href="/feature/core_protect/"><b>方塊紀錄查詢</b></a> <a class="header-anchor" href="#方塊紀錄查詢" aria-label="Permalink to &quot;[&lt;b&gt;方塊紀錄查詢&lt;/b&gt;](./feature/core_protect.md)&quot;">​</a></h3><ul><li><code>/co i</code><b>開啟/關閉查詢功能</b></li><li><code>/co near</code><b>查詢你所在位置附近的事件</b>(半徑5格內)</li></ul><h3 id="鎖箱子-門" tabindex="-1"><a href="/feature/lock/"><b>鎖箱子/門</b></a> <a class="header-anchor" href="#鎖箱子-門" aria-label="Permalink to &quot;[&lt;b&gt;鎖箱子/門&lt;/b&gt;](./feature/lock.md)&quot;">​</a></h3><ul><li>對箱子或門拿告示牌右鍵就可以上鎖，這樣別人就不能去動它 <ul><li><font color="red"><b><a href="/server/res/"><font color="red"><b>資源服</b></font></a>沒有鎖箱子/門</b></font></li></ul></li></ul><h3 id="金錢系統" tabindex="-1"><a href="/feature/money/"><b>金錢系統</b></a> <a class="header-anchor" href="#金錢系統" aria-label="Permalink to &quot;[&lt;b&gt;金錢系統&lt;/b&gt;](./feature/money.md)&quot;">​</a></h3><ul><li><code>/money</code><b>查詢自己有多少錢</b></li><li><code>/money pay &lt;玩家ID&gt; &lt;金額&gt;</code><b>給別人錢</b></li><li><code>/money lookup &lt;玩家ID&gt; &lt;頁數&gt;</code><b>查看交易紀錄</b></li></ul><h3 id="市場系統" tabindex="-1"><a href="/feature/market/"><b>市場系統</b></a> <a class="header-anchor" href="#市場系統" aria-label="Permalink to &quot;[&lt;b&gt;市場系統&lt;/b&gt;](./feature/market.md)&quot;">​</a></h3><div class="warning custom-block"><p class="custom-block-title">公告(2022/07/04)</p><p>市場系統的入門介紹正在編寫中，敬請期待<br> 如果需要查看相關內容，請先點選<a href="/feature/market/"><b>連結</b></a>查看詳細說明<br> 造成不便敬請見諒</p></div><h2 id="常用幫助" tabindex="-1">常用幫助 <a class="header-anchor" href="#常用幫助" aria-label="Permalink to &quot;常用幫助&quot;">​</a></h2><h3 id="連線問題" tabindex="-1"><a href="/help/connect_issue/">連線問題</a> <a class="header-anchor" href="#連線問題" aria-label="Permalink to &quot;[連線問題](./help/connect_issue.md)&quot;">​</a></h3>',54)])])}const p=a(i,[["render",o]]);export{u as __pageData,p as default};
